import { useMemo } from 'react'
import { get } from 'lodash'
import isObject from 'lodash/isObject'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { PROPERTY_PROTECTION } from '../../../../../constants/pkgCode'
import { LANG_STRINGS } from '../../../../../lang'
import BranchCard from '../BranchCard'
import DocumentDownload from '../DocumentDownload'
import { TransactionHeaderStyle } from './index.style'

function TransactionHeader(props) {
  const { policy, showDownload, documentUrl = '' } = props

  const isPropertyPolicy =
    get(policy, 'policy_detail.product_code', '') === PROPERTY_PROTECTION

  const branch = useMemo(() => {
    return policy?.insurance_details?.provider_branch
  }, [policy])

  return (
    <TransactionHeaderStyle>
      <div className="header-container">
        <img
          src={get(policy, 'product.provider.logo_url', '')}
          width={68}
          alt="provider-logo"
        />
        <CustomText color={AgentColorPallette.fontSecondary} textAlign="center">
          {get(policy, 'product.provider.name', '')}
        </CustomText>
        <CustomText
          color={AgentColorPallette.black}
          textAlign="center"
          weight="700"
          size="14px"
          top="4px"
        >
          {get(policy, 'product.name', '')}
        </CustomText>
        <CustomText
          color={AgentColorPallette.fontSemiGrey}
          textAlign="center"
          weight="700"
          size="12px"
          top="4px"
        >
          {LANG_STRINGS.transactionId}&nbsp;{policy.application_no}
        </CustomText>
        {showDownload && <DocumentDownload documentUrl={documentUrl} />}
        {!isPropertyPolicy && branch && isObject(branch) && (
          <BranchCard padding="20px" branch={branch} />
        )}
      </div>
    </TransactionHeaderStyle>
  )
}

export default TransactionHeader
