import CustomText from '../CustomText'
import { PolicyInfoStyle } from './index.style'
import PropTypes from 'prop-types'
import { LANG_STRINGS } from '../../lang'

function PolicyInfo (props) {
  const { status, remarks, marginTop = '' } = props

  // TODO: CONFIRM REJECTED STATUS FROM BACKEND
  if (status === 'CANCELLED' || status === 'REJECTED') {
    return (
      <PolicyInfoStyle marginTop={marginTop}>
        {
          <div className='remark-box'>
            <CustomText
              weight={800}
              size='13px'
            >
              {status === 'REJECTED' ? LANG_STRINGS.policyRejected : LANG_STRINGS.policyCancelled || ''}
            </CustomText>
            <CustomText
              size='10px'
              top='5px'
            >
              {status === 'REJECTED' ? LANG_STRINGS.policyReasonRejected : LANG_STRINGS.policyReasonCancellation || ''}
            </CustomText>
            <CustomText
              size='13px'
            >
              {remarks?.reason || ''}
            </CustomText>
          </div>
        }
      </PolicyInfoStyle>
    )
  } else {
    return null
  }
}

PolicyInfo.propTypes = {
  remarks: PropTypes.object
}

export default PolicyInfo
