import { CustomText } from '../../../../../components'
import { DocumentDownloadStyle } from './index.style'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../lang/index'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { DOWNLOAD_GREY, SHARE_GREY } from '../../../../../images'
import { Row } from '../../../../../commonStyle/index.style'
import { useCallback } from 'react'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { downloadFile } from '../../../../../helpers/mitraUtils/mitra-utility'

function DocumentDownload ({ documentUrl }) {
  const handleShare = useCallback(() => {
    if (navigator.share) {
      // Web Share API is supported
      navigator.share({
        title: LANG_STRINGS.share,
        text: documentUrl
      })
        .catch(console.error)
    } else if (window.PPBridge) {
      window.PPBridge.share(LANG_STRINGS.share, documentUrl)
    } else {
      // Fallback
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.shareOptionNotSupport
      })
    }
  }, [documentUrl])

  const handleDownloadFile = useCallback(() => {
    downloadFile(documentUrl)
  }, [documentUrl])

  return (
    <DocumentDownloadStyle>
      <CustomText
        color={AgentColorPallette.black}
        size='14px'
        weight={700}
      >
        {LANG_STRINGS.policyDocuments}
      </CustomText>
      <Row>
        <div onClick={handleDownloadFile} className='download-img-icon'>
          <img src={DOWNLOAD_GREY} alt='download' />
        </div>
        <div className='share-icon' onClick={handleShare}>
          <img src={SHARE_GREY} alt='share' />
        </div>
      </Row>
      <ShowSnackbar />
    </DocumentDownloadStyle>
  )
}

export default DocumentDownload
