import {
  resetError,
  updateLoader,
  useErrorContextValue,
  useLoaderContextValue,
} from '@pasarpolis/common-react-hooks'
import get from 'lodash/get'
import { useCallback, useEffect, useRef, useState } from 'react'
import { withRouter } from 'react-router'
import { Container, CustomText } from '../../../../../../../components'
import CollapsibleTable from '../../../../../../../components/CollapsibleTable'
import ShowSnackbar from '../../../../../../../components/ShowNotification'
import StepsHeader from '../../../../../../../components/StepsHeader'
import { getParamsFromUri } from '../../../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../../../lang'
import TransactionHeader from '../../../../../../Private/Policy/components/TransactionHeader'
import {
  useGetCustomerApplicationDetail,
  useSubmitCustomerPolicy,
} from '../../../state/hooks/useMarineCargo'
import { MarineCargoPreviewStyle } from './index.style'
import {
  getAgentDetailData,
  getPolicyDetailCard,
  getTransactionDetailData,
  getItemDetailCard,
  getDeliveryDetailCard,
  getAttachmentDetailCard,
  getCustomerDetailCard,
  getHardcopyDetailCard,
} from '../../../constants/index'
import { DisplayFlexRCC } from '../../../../../../../commonStyle/index.style'
import CustomCheckbox from '../../../../../../../components/CustomCheckbox'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import ButtonWithIcon from '../../../../../../../components/ButtonWithIcon'
import { SEND_GOLD_ICON } from '../../../../../../../images'
import InsuranceInfoCard from '../../../../../../../components/InsuranceInfoCard'
import TransactionCard from '../../../../../../../components/TransactionCard'
import PolicyInfo from '../../../../../../../components/PolicyCancelledRejectionInfo'
import TermsNConditionModal from '../../../../../../Private/Application/components/TermsNConditionModal'

function MarineCargoPreview(props) {
  const policyId = getParamsFromUri.call({ props }, 'policyId')
  const [isTermsChecked, setIsTermsChecked] = useState(false)
  const [showTermsModal, setShowTermsModal] = useState(false)
  const isInitialRender = useRef(true)

  const [
    { GET_CUSTOMER_APPLICATION_DETAIL_LOADER, SUBMIT_CUSTOMER_POLICY_LOADER },
    dispatchLoader,
  ] = useLoaderContextValue()
  const [
    { getCustomerApplicationDetailData = {} },
    getCustomerApplicationDetailRequest,
  ] = useGetCustomerApplicationDetail()
  const [, submitCustomerPolicyRequest] = useSubmitCustomerPolicy()
  const [
    {
      GET_CUSTOMER_APPLICATION_DETAIL_ERROR,
      getCustomerApplicationDetailStatus,
      SUBMIT_CUSTOMER_POLICY_ERROR,
      submitCustomerPolicyStatus,
    },
    dispatchError,
  ] = useErrorContextValue()

  useEffect(() => {
    if (isInitialRender.current) {
      getCustomerApplicationDetailRequest({
        policyId: policyId,
      })
      isInitialRender.current = false
    }
  }, [
    getCustomerApplicationDetailRequest,
    GET_CUSTOMER_APPLICATION_DETAIL_LOADER,
    policyId,
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          GET_CUSTOMER_APPLICATION_DETAIL_LOADER: undefined,
          SUBMIT_CUSTOMER_POLICY_LOADER: undefined,
        })
      )
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (
      GET_CUSTOMER_APPLICATION_DETAIL_ERROR &&
      getCustomerApplicationDetailStatus
    ) {
      ShowSnackbar.error({
        visible: true,
        text: getCustomerApplicationDetailStatus,
      })
      dispatchError(
        resetError({
          getCustomerApplicationDetailStatus: '',
        })
      )
    }
    if (SUBMIT_CUSTOMER_POLICY_ERROR && submitCustomerPolicyStatus) {
      ShowSnackbar.error({
        visible: true,
        text: submitCustomerPolicyStatus,
      })
      dispatchError(
        resetError({
          submitCustomerPolicyStatus: '',
        })
      )
    }
    if (submitCustomerPolicyStatus === 'success') {
      props.history.push(
        `/customer/payment/${getCustomerApplicationDetailData?.product_key}/${policyId}`
      )
      dispatchError(
        resetError({
          submitCustomerPolicyStatus: '',
        })
      )
    }
  }, [
    SUBMIT_CUSTOMER_POLICY_ERROR,
    submitCustomerPolicyStatus,
    getCustomerApplicationDetailStatus,
    getCustomerApplicationDetailData,
    dispatchError,
    GET_CUSTOMER_APPLICATION_DETAIL_ERROR,
    props.history,
    policyId,
  ])

  const handleSubmit = useCallback(() => {
    if (getCustomerApplicationDetailData.status === 'INITIATED') {
      submitCustomerPolicyRequest({
        policyId: policyId,
      })
    } else {
      props.history.push(
        `/customer/payment/${getCustomerApplicationDetailData?.product_key}/${policyId}`
      )
    }
  }, [
    submitCustomerPolicyRequest,
    policyId,
    getCustomerApplicationDetailData,
    props.history,
  ])

  const handleTermsCheckBox = useCallback((useCase) => {
    setIsTermsChecked(useCase)
    setShowTermsModal(false)
  }, [])

  const isApplicationCancelled = ['CANCELLED', 'REJECTED'].includes(
    getCustomerApplicationDetailData?.policy_status
  )
  return (
    <Container
      mitraHeader
      hideBottomTabs
      loader={
        GET_CUSTOMER_APPLICATION_DETAIL_LOADER || SUBMIT_CUSTOMER_POLICY_LOADER
      }
    >
      <MarineCargoPreviewStyle>
        <PolicyInfo
          remarks={
            getCustomerApplicationDetailData?.insurance_details
              ?.remark_details || {}
          }
          status={getCustomerApplicationDetailData?.policy_status || ''}
        />
        <StepsHeader
          leftText="Kargo"
          className="mt-0"
          current="2"
          totalSteps="4"
        />
        <TransactionHeader policy={getCustomerApplicationDetailData} />
        <div className="content">
          <InsuranceInfoCard
            isShowDisclaimer
            tnc={get(getCustomerApplicationDetailData, 'product.tnc.data', [])}
            benefit={get(
              getCustomerApplicationDetailData,
              'product.benefit.data[0].description',
              ''
            )}
            claims={get(
              getCustomerApplicationDetailData,
              'product.claims.[0].description',
              ''
            )}
          />

          <CollapsibleTable
            title={LANG_STRINGS.agentDetails}
            items={getAgentDetailData(getCustomerApplicationDetailData)}
          />

          <TransactionCard
            disableDiscountEdit
            commission={get(
              getCustomerApplicationDetailData,
              'product.commission'
            )}
            maxDiscount={get(
              getCustomerApplicationDetailData,
              'product.max_discount'
            )}
            subTotal={get(
              getCustomerApplicationDetailData,
              'product.sub_total'
            )}
            discountPercent={get(
              getCustomerApplicationDetailData,
              'product.discount_percentage'
            )}
            basicPremium={get(
              getCustomerApplicationDetailData,
              'product.basic_premium'
            )}
            totalTax={get(getCustomerApplicationDetailData, 'total_tax')}
            stampDuty={get(getCustomerApplicationDetailData, 'stamp_duty')}
            adminFee={get(getCustomerApplicationDetailData, 'admin_fee')}
            serviceFee={get(getCustomerApplicationDetailData, 'service_fee')}
            discount={get(getCustomerApplicationDetailData, 'discount')}
            totalBill={
              get(getCustomerApplicationDetailData, 'subtotal_bill') +
              get(getCustomerApplicationDetailData, 'discount')
            }
            handleEditDiscount={() => {}}
          />

          <CollapsibleTable
            title={LANG_STRINGS.transactionDetail}
            items={getTransactionDetailData(getCustomerApplicationDetailData)}
          />

          <CollapsibleTable
            title={LANG_STRINGS.policyDetails}
            items={getPolicyDetailCard(getCustomerApplicationDetailData)}
          />

          <hr className="separator" />

          <CustomText
            color={AgentColorPallette.black}
            size="15px"
            weight={800}
            bottom="15px"
            top="10px"
          >
            {LANG_STRINGS.dataChecking}
          </CustomText>
          <CollapsibleTable
            title={LANG_STRINGS.itemDetails}
            items={getItemDetailCard(getCustomerApplicationDetailData)}
          />

          <CollapsibleTable
            title={LANG_STRINGS.delivery}
            items={getDeliveryDetailCard(getCustomerApplicationDetailData)}
          />
          <CollapsibleTable
            title={LANG_STRINGS.attachment}
            items={getAttachmentDetailCard(getCustomerApplicationDetailData)}
          />
          <CollapsibleTable
            title={LANG_STRINGS.customerData}
            items={getCustomerDetailCard(getCustomerApplicationDetailData)}
          />
          <CollapsibleTable
            title={LANG_STRINGS.printPolicy}
            items={getHardcopyDetailCard(getCustomerApplicationDetailData)}
          />
          {!isApplicationCancelled && (
            <DisplayFlexRCC onClick={() => setShowTermsModal(!showTermsModal)}>
              <CustomCheckbox isChecked={isTermsChecked} />
              <CustomText
                color={AgentColorPallette.black}
                weight={700}
                dangerouslySetInnerHTML={{
                  __html: LANG_STRINGS.agreeWithTermsConditionsCargo,
                }}
              />
            </DisplayFlexRCC>
          )}
        </div>
        {!isApplicationCancelled && (
          <div className="bottom-action-container">
            <DisplayFlexRCC className="bottom-continue-btn">
              <ButtonWithIcon
                disabled={!isTermsChecked}
                id="cargoStepSubmit_4"
                className="start-btn"
                text={LANG_STRINGS.makePayment}
                icon={SEND_GOLD_ICON}
                iconRight
                onClick={handleSubmit}
              />
            </DisplayFlexRCC>
          </div>
        )}
        {showTermsModal && (
          <TermsNConditionModal
            isOpen={showTermsModal}
            tncData={getCustomerApplicationDetailData.product.tnc.data}
            onAccept={() => handleTermsCheckBox(true)}
            onReject={() => handleTermsCheckBox(false)}
          />
        )}
        <ShowSnackbar hideOkay />
      </MarineCargoPreviewStyle>
    </Container>
  )
}

export default withRouter(MarineCargoPreview)
