import { Component } from 'react'
import PropTypes from 'prop-types'
import { Button, CustomText } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang'
import { TermsContainerStyle, TermsStyle } from './index.style'
import ModifyTermsConditions from '../../../../../components/TermsCondition/components/ModifytTermsConditions'
import BottomActionSheet from '../../../../../components/BottomActionSheet'
import DisclaimerBox from '../../../../../components/DisclaimerBox'
import { AgentColorPallette } from '../../../../../configs/colorPallete'

class TermsNConditionModal extends Component {
  static propTypes = {
    isOpen: PropTypes.bool,
    tncData: PropTypes.array,
    onAccept: PropTypes.func,
    onReject: PropTypes.func,
    isNewStructure: PropTypes.bool
  }

  state = {
    isDisabled: true
  }

  componentDidMount () {
    const scrollDiv = document.getElementById('terms-body-content')
    const contentElement = document.getElementById('terms-content')
    const scrollHandler = () => {
      // this is the handler function run for scroll
      const scrollDivBoundingClientReact = scrollDiv.getBoundingClientRect()
      if (this.state.isDisabled && contentElement.getBoundingClientRect().bottom < scrollDivBoundingClientReact.bottom) {
        // once the button active then simple active the disable button
        // and remove the event listener
        this.setState({
          isDisabled: false
        })
        scrollDiv.removeEventListener('scroll', scrollHandler, true)
      }
    }
    scrollDiv.addEventListener('scroll', scrollHandler, true)
  }

  renderNewStructure = (tncData) => {
    return tncData?.map((section, sectionIndex) => (
      <div key={`section_${sectionIndex}`}>
        {section.main_heading && (
          <CustomText
            color={AgentColorPallette.black}
            size='15px'
            bottom='15px'
            lineHeight={1.5}
            weight='600'
          >
            {section.main_heading}
          </CustomText>
        )}
        {
          section.tnc_list?.map((tncItem, tncIndex) => (
            <div key={`tnc_${sectionIndex}_${tncIndex}`} style={{ marginBottom: '20px' }}>
              {tncItem.title && (
                <CustomText
                  color={AgentColorPallette.black}
                  size='14px'
                  bottom='10px'
                  lineHeight={1.5}
                  weight='600'
                >
                  {tncItem.title}
                </CustomText>
              )}
              {tncItem.description && (
                <CustomText
                  color={AgentColorPallette.black}
                  size='13px'
                  bottom='10px'
                  lineHeight={1.5}
                >
                  {tncItem.description}
                </CustomText>
              )}
              {tncItem.items?.length > 0 && (
                <div style={{ paddingLeft: '15px' }}>
                  {tncItem.items?.map((item, itemIndex) => (
                    <CustomText
                      color={AgentColorPallette.black}
                      size='13px'
                      bottom='8px'
                      key={`item_${sectionIndex}_${tncIndex}_${itemIndex}`}
                      lineHeight={1.5}
                    >
                      {itemIndex + 1}. {item}
                    </CustomText>
                  ))}
                </div>
              )}
              {tncItem.notes && (
                <CustomText
                  color={AgentColorPallette.black}
                  size='13px'
                  bottom='10px'
                  lineHeight={1.5}
                >
                  {tncItem.notes}
                </CustomText>
              )}
            </div>
          ))
        }
      </div>
    ))
  }

  render () {
    const { isOpen, onAccept, onReject, tncData, isNewStructure } = this.props

    return (
      <TermsContainerStyle>
        <BottomActionSheet
          show={isOpen}
          onCloseSheet={onReject}
        >
          <TermsStyle id='terms-body-content'>
            <div className='p-15'>
              <DisclaimerBox /> <br />
              {
                isNewStructure ? (
                  this.renderNewStructure(tncData)
                ) : Array.isArray(tncData) ? (
                  tncData.map((term, index) => (
                    <p className='terms-font' key={index} dangerouslySetInnerHTML={{ __html: `${index + 1}. ${term}` }} />
                  ))
                ) : (
                  <ModifyTermsConditions data={tncData} />
                )
              }
              <div id='terms-content' />
            </div>
          </TermsStyle>
          <div className='p-15'>
            <Button className='mb-10' handleClick={onAccept} disabled={this.state.isDisabled}>
              {LANG_STRINGS.agreeNew}
            </Button>

            <Button handleClick={onReject}>
              {LANG_STRINGS.disagree}
            </Button>
          </div>
        </BottomActionSheet>
      </TermsContainerStyle>
    )
  }
}

export default TermsNConditionModal
